using Microsoft.Maui.Controls.Shapes;
namespace MeetMindAI.Mobile.Views; public class HomePage:ContentPage{public HomePage(){Title="MeetMind AI";var start=new Button{Text="＋  Start New Meeting",HeightRequest=56};start.Clicked+=async(_,_)=>await Navigation.PushAsync(new LiveMeetingPage());var history=new Button{Text="Meeting History",BackgroundColor=Color.FromArgb("#E9EAFD"),TextColor=Color.FromArgb("#3F46C6")};history.Clicked+=async(_,_)=>await Navigation.PushAsync(new HistoryPage());Content=new ScrollView{Content=new VerticalStackLayout{Padding=24,Spacing=18,Children={new Label{Text="Good morning 👋",FontSize=28,FontAttributes=FontAttributes.Bold},new Label{Text="What would you like to do today?",TextColor=Colors.Gray},start,history,new Border{StrokeShape=new RoundRectangle{CornerRadius=18},Padding=20,Content=new VerticalStackLayout{Children={new Label{Text="AI Meeting Copilot",FontSize=20,FontAttributes=FontAttributes.Bold},new Label{Text="Listen • Understand • Suggest • Summarize",TextColor=Colors.Gray}}}}}}};}}
